WITH latest_match AS (SELECT s.*, top1.store_sale_revenue, top1.units FROM products s JOIN LATERAL (SELECT c.revenue AS store_sale_revenue, c.units FROM store_sales c WHERE c.product_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, product_name, category, brand, cost, launch_date, tags, supplier_id, store_sale_revenue FROM latest_match ORDER BY id DESC;
